function backfillAgentType(database) {
  const row = database.query("SELECT value FROM meta WHERE key = ?").get(AGENT_TYPE_BACKFILL_KEY);
  if (row?.value !== BACKFILL_PENDING)
    return;
  const sessionFiles = database.query("SELECT DISTINCT session_file FROM messages").all();
  const update = database.query("UPDATE messages SET agent_type = ? WHERE session_file = ?");
  const markComplete = database.query("INSERT OR REPLACE INTO meta (key, value) VALUES (?, ?)");
  const apply = database.transaction(() => {
    for (const { session_file } of sessionFiles) {
      const agentType = classifyAgentType(session_file);
      if (agentType !== "main")
        update.run(agentType, session_file);
    }
    markComplete.run(AGENT_TYPE_BACKFILL_KEY, BACKFILL_COMPLETE);
  });
  apply();
}
function backfillForkDuplicates(database) {
  const row = database.query("SELECT value FROM meta WHERE key = ?").get(FORK_DEDUPE_KEY);
  if (row?.value === BACKFILL_COMPLETE)
    return;
  const markComplete = database.query("INSERT OR REPLACE INTO meta (key, value) VALUES (?, ?)");
  const apply = database.transaction(() => {
    database.run(`
			DELETE FROM messages
			WHERE id NOT IN (
				SELECT MIN(id) FROM messages GROUP BY entry_id, timestamp
			)
		`);
    database.run(`
			DELETE FROM user_messages
			WHERE id NOT IN (
				SELECT MIN(id) FROM user_messages GROUP BY entry_id, timestamp
			)
		`);
    markComplete.run(FORK_DEDUPE_KEY, BACKFILL_COMPLETE);
  });
  apply();
}
